3	/**
4	 * DB-backed email rendering.
5	 *
6	 * Templates live in the `EmailTemplate` table (admin-editable). Each row stores
7	 * a `subject` and an HTML *body* containing `{{variable}}` placeholders. At send
8	 * time we load the row, substitute the variables, and wrap the body in the
9	 * shared branded shell (header/footer). If a template is missing or disabled we
10	 * fall back to a minimal built-in default so a send never silently produces an
11	 * empty email.
12	 *
13	 * This module has NO dependency on `lib/mailer.ts` (mailer depends on it), which
14	 * keeps the import graph acyclic.
15	 */
16	
17	const BRAND = { blue: "#4b8bf5", purple: "#9a7cff", grad: "#6f7bf7", bg: "#070b16", card: "#0e1730" };
18	const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
19	
20	export function appUrl(): string {
21	  return process.env.APP_URL ?? "https://nxeon.cloud";
22	}
23	
24	/**
25	 * Shared premium email shell. Table-based + inline styles for broad client
26	 * compatibility (Gmail/Outlook/Apple Mail). Dark, brand-aligned, with the Nxeon
27	 * logo, a gradient accent, and a proper footer. Gradients fall back to a solid
28	 * `background-color` in clients that strip them.
29	 */
30	export function wrapEmail(bodyHtml: string): string {
31	  const url = appUrl();
32	  return `<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="color-scheme" content="dark"/><title>Nxeon</title></head>
33	<body style="margin:0;padding:0;background-color:${BRAND.bg};">
34	  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:${BRAND.bg};">
35	    <tr><td align="center" style="padding:34px 16px;">
36	      <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;">
37	        <tr><td align="center" style="padding:0 0 20px;">
38	          <img src="${url}/logo.png" alt="Nxeon" height="40" style="height:40px;width:auto;display:block;" />
39	        </td></tr>
40	        <tr><td style="background-color:${BRAND.card};border:1px solid rgba(255,255,255,0.08);border-radius:18px;overflow:hidden;">
41	          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
42	            <tr><td style="height:5px;line-height:5px;font-size:0;background-color:${BRAND.grad};background-image:linear-gradient(90deg,${BRAND.blue},${BRAND.purple});">&nbsp;</td></tr>
43	            <tr><td style="padding:36px 38px 32px;font-family:${FONT};font-size:15px;line-height:1.65;color:#c9d4e8;">
44	              ${bodyHtml}
45	            </td></tr>
46	          </table>
47	        </td></tr>
48	        <tr><td align="center" style="padding:22px 12px 0;font-family:${FONT};font-size:12px;color:#5a6b86;">
49	          <a href="${url}/dashboard" style="color:${BRAND.purple};text-decoration:none;margin:0 9px;">Dashboard</a>
50	          <a href="${url}/help" style="color:${BRAND.purple};text-decoration:none;margin:0 9px;">Help center</a>
51	          <a href="${url}/dashboard/support" style="color:${BRAND.purple};text-decoration:none;margin:0 9px;">Support</a>
52	          <div style="border-top:1px solid rgba(255,255,255,0.07);margin:16px auto;width:80%;"></div>
53	          <div style="color:#8ea0be;font-weight:600;letter-spacing:.3px;">NXEON CLOUD</div>
54	          <div style="margin-top:5px;color:#4a5a76;">High-performance NVMe VPS · game servers · domains</div>
55	          <div style="margin-top:10px;color:#3d4c67;">You're receiving this because you have a Nxeon account.</div>
56	        </td></tr>
57	      </table>
58	    </td></tr>
59	  </table>
60	</body></html>`;
61	}
