63	/** Branded CTA button — bulletproof-ish (inline styles + solid fallback). */
64	export function emailButton(href: string, label: string): string {
65	  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:22px 0;"><tr><td align="center" style="border-radius:12px;background-color:${BRAND.grad};background-image:linear-gradient(90deg,${BRAND.blue},${BRAND.purple});">
66	    <a href="${href}" style="display:inline-block;padding:13px 30px;font-family:${FONT};font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:12px;">${label}</a>
67	  </td></tr></table>`;
68	}
