70	/** Replace `{{ var }}` placeholders with values from `vars` (missing → empty). */
71	export function substitute(input: string, vars: Record<string, unknown>): string {
72	  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key: string) => {
73	    const v = vars[key];
74	    return v === undefined || v === null ? "" : String(v);
75	  });
76	}
77	
78	/**
79	 * Minimal built-in defaults used when a template row is missing or disabled.
80	 * These are intentionally plain — the real, branded copy lives in the DB (see
81	 * `prisma/seed-email-templates.ts`).
82	 */
83	const DEFAULTS: Record<string, { subject: string; body: string }> = {
84	  welcome: {
85	    subject: "Welcome to Nxeon",
86	    body: `<h1 style="margin:0 0 14px;font-size:19px;color:#fff">Welcome, {{name}}!</h1><p>Your Nxeon account is ready. Deploy your first NVMe VPS in minutes.</p>`,
87	  },
88	  password_reset: {
89	    subject: "Reset your Nxeon password",
90	    body: `<h1 style="margin:0 0 14px;font-size:19px;color:#fff">Reset your password</h1><p>Use the link below to set a new password. It expires in 1 hour.</p><p><a href="{{resetUrl}}" style="color:#8a70fb">{{resetUrl}}</a></p>`,
91	  },
92	};
93	
94	const GENERIC_FALLBACK = (key: string) => ({
95	  subject: "A message from Nxeon",
96	  body: `<h1 style="margin:0 0 14px;font-size:19px;color:#fff">Nxeon</h1><p>This notification (<code>${key}</code>) has no configured template.</p>`,
97	});
98	
99	export type RenderedEmail = { subject: string; html: string; template: string };
100	
101	/**
102	 * Render a stored (or default) template for `key`, substituting `vars`,
103	 * returning the final subject and full wrapped HTML ready to send/preview.
104	 */
105	export async function renderTemplate(key: string, vars: Record<string, unknown> = {}): Promise<RenderedEmail> {
106	  let subject: string;
107	  let body: string;
108	
109	  let row: { subject: string; html: string; enabled: boolean } | null = null;
110	  try {
111	    row = await db.emailTemplate.findUnique({
112	      where: { key },
113	      select: { subject: true, html: true, enabled: true },
114	    });
115	  } catch {
116	    row = null;
117	  }
118	
119	  if (row && row.enabled) {
120	    subject = row.subject;
121	    body = row.html;
122	  } else {
123	    const d = DEFAULTS[key] ?? GENERIC_FALLBACK(key);
124	    subject = d.subject;
125	    body = d.body;
126	  }
127	
128	  return {
129	    template: key,
130	    subject: substitute(subject, vars),
131	    html: wrapEmail(substitute(body, vars)),
132	  };
133	}
134	
135	/**
136	 * Render a *draft* (unsaved) subject/body with sample vars — used by the admin
137	 * editor's live preview and by the seed preview. Same wrapping as a real send.
138	 */
139	export function renderDraft(subject: string, body: string, vars: Record<string, unknown> = {}): RenderedEmail {
140	  return {
141	    template: "draft",
142	    subject: substitute(subject, vars),
143	    html: wrapEmail(substitute(body, vars)),
144	  };
145	}
