147	/**
148	 * Append an `EmailLog` row for every send attempt. Never throws (logging must
149	 * not break a mail flow).
150	 */
151	export async function recordEmail(
152	  toEmail: string,
153	  subject: string,
154	  template: string | null,
155	  html: string,
156	  status: "SENT" | "FAILED",
157	  error?: string | null,
158	  userId?: string | null,
159	): Promise<void> {
160	  try {
161	    await db.emailLog.create({
162	      data: {
163	        toEmail,
164	        subject: subject.slice(0, 500),
165	        template: template ?? null,
166	        html,
167	        status,
168	        error: error ? String(error).slice(0, 1000) : null,
169	        userId: userId ?? null,
170	      },
171	    });
172	  } catch (e) {
173	    console.error("[email-render] failed to record EmailLog:", e);
174	  }
175	}
