1	import nodemailer from "nodemailer";
2	import { db } from "./db";
3	import { renderTemplate, recordEmail, wrapEmail, emailButton, appUrl as renderAppUrl } from "./email-render";
4	import { renderInvoiceHTML } from "./invoices";
5	
6	/**
7	 * SMTP config comes from the Setting table (admin-editable) with env fallback.
8	 * Keys: smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from, smtp_secure.
9	 * If nothing is configured, falls back to a local sendmail/Postfix relay on :25.
10	 */
11	async function loadSmtp() {
12	  const rows = await db.setting.findMany({
13	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
14	  });
15	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
16	  const host = s.smtp_host || process.env.SMTP_HOST || "";
17	  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
18	  return {
19	    host,
20	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
21	    user: s.smtp_user || process.env.SMTP_USER || "",
22	    pass: s.smtp_pass || process.env.SMTP_PASS || "",
23	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
24	    from,
25	  };
26	}
27	
28	export async function mailConfigured(): Promise<boolean> {
29	  const c = await loadSmtp();
30	  return !!c.host || process.env.NXEON_LOCAL_MAIL === "1";
31	}
32	
33	function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
34	  if (!c.host) {
35	    // Local MTA fallback (Postfix/sendmail on the host)
36	    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
37	  }
38	  // When the SMTP host is an internal IP (e.g. the mail VM at 10.20.0.10) but the
39	  // server presents a cert for its hostname (mail.nxeon.cloud), TLS validation
40	  // fails on an IP mismatch. `SMTP_TLS_SERVERNAME` lets us keep cert verification
41	  // on while telling TLS the name to validate against (and sets SNI accordingly).
42	  const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
43	  return nodemailer.createTransport({
44	    host: c.host,
45	    port: c.port,
46	    secure: c.secure,
47	    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
48	    ...(servername ? { tls: { servername } } : {}),
49	  });
50	}
