14	/**
15	 * Left-rail selector + sandboxed live preview of a transactional email.
16	 * The HTML is rendered inside an isolated iframe (sandbox, no scripts) so the
17	 * email's inline styles can't leak into the admin panel.
18	 */
19	export function EmailTemplatePreview({ templates }: { templates: EmailTemplate[] }) {
20	  const [active, setActive] = useState(templates[0]?.key ?? "");
21	  const current = templates.find((t) => t.key === active) ?? templates[0];
22	
23	  if (!current) return null;
24	
25	  return (
26	    <div className="grid gap-5 lg:grid-cols-[240px_1fr]">
27	      {/* Selector */}
28	      <div className="card h-fit p-2">
29	        <div className="space-y-0.5">
30	          {templates.map((t) => (
31	            <button
32	              key={t.key}
33	              onClick={() => setActive(t.key)}
34	              className={`nav-item w-full text-left ${t.key === active ? "nav-item-active" : ""}`}
35	            >
36	              <span className="truncate">{t.label}</span>
37	            </button>
38	          ))}
39	        </div>
40	      </div>
41	
42	      {/* Preview */}
43	      <div className="space-y-4">
44	        <div className="card p-5">
45	          <p className="section-label">Subject line</p>
46	          <p className="mt-1 text-base font-semibold text-white">{current.subject}</p>
47	          <p className="mt-3 text-xs text-slate-400">{current.description}</p>
48	          <div className="mt-3">
49	            <p className="section-label">Sample data</p>
50	            <code className="mt-1 block overflow-x-auto rounded-lg bg-black/30 px-3 py-2 font-mono text-xs text-brand-300">
51	              emails.{current.key}({current.sampleArgs})
52	            </code>
53	          </div>
54	        </div>
55	
56	        <div className="card overflow-hidden p-0">
57	          <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-2.5">
58	            <p className="text-xs font-medium text-slate-400">Rendered preview</p>
59	            <p className="text-[11px] text-slate-600">sandboxed · sample data</p>
60	          </div>
61	          <iframe
62	            title={`${current.label} preview`}
63	            srcDoc={current.html}
64	            sandbox=""
65	            className="h-[640px] w-full border-0 bg-white"
66	          />
67	        </div>
68	      </div>
69	    </div>
70	  );
71	}
