import { db } from "@/lib/db";

/**
 * DB-backed email rendering + the shared branded email shell.
 *
 * Templates live in the `EmailTemplate` table (admin-editable). Each row stores
 * a `subject` and an HTML *body* containing `{{variable}}` placeholders. At send
 * time we load the row, substitute the variables, and wrap the body in the
 * shared branded shell (header/footer). If a template is missing or disabled we
 * fall back to a minimal built-in default so a send never silently produces an
 * empty email.
 *
 * DESIGN (2026 refresh): a light, deliverability-safe theme. Real-world inbox
 * data shows light emails land in the primary tab more reliably than dark ones,
 * so the body is a soft violet-tinted background with a white content card and a
 * violet accent header carrying the Nxeon wordmark. Everything is table-based
 * with fully inline styles — Gmail/Outlook/Apple-Mail strip <style>, flexbox and
 * external CSS, so none of those are used. Gradients degrade to a solid
 * `background-color` fallback in clients that drop `background-image`.
 *
 * This module has NO dependency on `lib/mailer.ts` (mailer depends on it), which
 * keeps the import graph acyclic.
 */

/** Brand palette — violet primary (#8a70fb / #6f47f5) on a light, navy-ink card. */
export const BRAND = {
  // Header / primary accent
  violet: "#6f47f5",
  violetLight: "#8a70fb",
  violetDeep: "#5f2ee8",
  // Surfaces
  pageBg: "#eef0f8",
  card: "#ffffff",
  panel: "#f6f5fd",
  panelBorder: "#e7e3f7",
  hair: "#ecebf3",
  // Ink
  ink: "#1c1638",
  body: "#4a4763",
  muted: "#8a86a3",
  faint: "#a7a4bd",
  // Status
  success: "#15a34a",
  successBg: "#e9f8ef",
  warn: "#c2790b",
  warnBg: "#fdf3e3",
  danger: "#dc2626",
  dangerBg: "#fdecec",
  info: "#6f47f5",
  infoBg: "#f1edfe",
};
const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";

export function appUrl(): string {
  return process.env.APP_URL ?? "https://nxeon.cloud";
}

const esc = (s: unknown) =>
  String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

// ---------------------------------------------------------------------------
// Reusable, fully-inline email components. Every template composes these so the
// look stays consistent. All return an HTML string.
// ---------------------------------------------------------------------------

export type Accent = "violet" | "success" | "warn" | "danger" | "info";
const accentColor = (a: Accent = "violet") =>
  a === "success" ? BRAND.success : a === "warn" ? BRAND.warn : a === "danger" ? BRAND.danger : BRAND.violet;
const accentBg = (a: Accent = "violet") =>
  a === "success" ? BRAND.successBg : a === "warn" ? BRAND.warnBg : a === "danger" ? BRAND.dangerBg : BRAND.infoBg;

/** Small uppercase eyebrow/kicker label above the headline. */
export function emailEyebrow(text: string, accent: Accent = "violet"): string {
  return `<div style="margin:0 0 12px;font-family:${FONT};font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:${accentColor(accent)};">${esc(text)}</div>`;
}

/** Main headline. */
export function emailHeading(text: string): string {
  return `<h1 style="margin:0 0 14px;font-family:${FONT};font-size:23px;line-height:1.3;font-weight:700;color:${BRAND.ink};">${esc(text)}</h1>`;
}

/** Body paragraph. `html` may contain trusted inline markup (links, <b>). */
export function emailParagraph(html: string): string {
  return `<p style="margin:0 0 16px;font-family:${FONT};font-size:15px;line-height:1.65;color:${BRAND.body};">${html}</p>`;
}

/** Small muted note (fine print, alternate-link fallback, etc). */
export function emailNote(html: string): string {
  return `<p style="margin:16px 0 0;font-family:${FONT};font-size:13px;line-height:1.6;color:${BRAND.muted};">${html}</p>`;
}

/** Bulletproof CTA button (VML-free but padding-based so it survives Outlook). */
export function emailButton(href: string, label: string, accent: Accent = "violet"): string {
  const bg = accentColor(accent);
  const grad = accent === "violet" ? `background-image:linear-gradient(90deg,${BRAND.violet},${BRAND.violetLight});` : "";
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 6px;"><tr><td align="center" style="border-radius:12px;background-color:${bg};${grad}">
    <a href="${href}" style="display:inline-block;padding:14px 34px;font-family:${FONT};font-size:15px;font-weight:600;line-height:1;color:#ffffff;text-decoration:none;border-radius:12px;">${esc(label)}</a>
  </td></tr></table>`;
}

/** Soft rounded panel used to frame a details table / highlighted content. */
export function emailPanel(innerHtml: string, accent?: Accent): string {
  const border = accent ? accentColor(accent) : BRAND.panelBorder;
  const leftRule = accent ? `border-left:4px solid ${accentColor(accent)};` : `border:1px solid ${BRAND.panelBorder};`;
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 18px;background-color:${BRAND.panel};${leftRule}border-radius:12px;">
    <tr><td style="padding:18px 20px;">${innerHtml}</td></tr></table>`;
}

/** Colored status banner (e.g. suspended / payment failed / success). */
export function emailBanner(html: string, accent: Accent = "info"): string {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 18px;background-color:${accentBg(accent)};border-radius:12px;border-left:4px solid ${accentColor(accent)};">
    <tr><td style="padding:14px 18px;font-family:${FONT};font-size:14px;line-height:1.55;color:${BRAND.ink};font-weight:600;">${html}</td></tr></table>`;
}

/** Key/value details table (two columns, hairline rows). Values may hold markup. */
export function emailKeyValue(rows: Array<[string, string]>): string {
  const body = rows
    .map(
      ([k, v], i) =>
        `<tr>
          <td style="padding:11px 0;${i ? `border-top:1px solid ${BRAND.hair};` : ""}font-family:${FONT};font-size:13px;color:${BRAND.muted};vertical-align:top;white-space:nowrap;">${esc(k)}</td>
          <td align="right" style="padding:11px 0 11px 16px;${i ? `border-top:1px solid ${BRAND.hair};` : ""}font-family:${FONT};font-size:14px;font-weight:600;color:${BRAND.ink};vertical-align:top;">${v}</td>
        </tr>`
    )
    .join("");
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${body}</table>`;
}

/** Monospace code / command block (e.g. an SSH command). */
export function emailCode(text: string): string {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 18px;background-color:#1c1638;border-radius:10px;">
    <tr><td style="padding:14px 16px;font-family:'SFMono-Regular',Consolas,'Liberation Mono',Menlo,monospace;font-size:13px;line-height:1.5;color:#d7d2f5;word-break:break-all;">${esc(text)}</td></tr></table>`;
}

/** Thin divider. */
export function emailDivider(): string {
  return `<div style="border-top:1px solid ${BRAND.hair};margin:22px 0;line-height:1px;font-size:0;">&nbsp;</div>`;
}

/**
 * The premium email shell. Wraps composed body HTML in the branded, responsive,
 * client-safe layout: soft page background → white card with a violet header
 * carrying the wordmark → content → footer. `opts.preheader` sets the hidden
 * inbox-preview snippet.
 */
export function wrapEmail(bodyHtml: string, opts: { preheader?: string } = {}): string {
  const url = appUrl();
  const preheader = opts.preheader
    ? `<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:${BRAND.pageBg};opacity:0;">${esc(opts.preheader)}&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;</div>`
    : "";
  return `<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta http-equiv="X-UA-Compatible" content="IE=edge"/><meta name="color-scheme" content="light"/><meta name="supported-color-schemes" content="light"/><title>Nxeon</title></head>
<body style="margin:0;padding:0;background-color:${BRAND.pageBg};-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;">
  ${preheader}
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:${BRAND.pageBg};">
    <tr><td align="center" style="padding:32px 14px;">
      <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;margin:0 auto;">
        <tr><td style="border-radius:18px;overflow:hidden;background-color:${BRAND.card};box-shadow:0 8px 30px rgba(40,25,90,0.10);">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
            <!-- Header -->
            <tr><td align="center" style="padding:30px 40px 28px;background-color:${BRAND.violet};background-image:linear-gradient(120deg,${BRAND.violetDeep},${BRAND.violetLight});">
              <img src="${url}/logo.png" alt="Nxeon" height="30" style="height:30px;width:auto;display:block;border:0;outline:none;text-decoration:none;" />
            </td></tr>
            <!-- Content -->
            <tr><td style="padding:38px 40px 34px;">
              ${bodyHtml}
            </td></tr>
          </table>
        </td></tr>
        <!-- Footer -->
        <tr><td align="center" style="padding:24px 20px 6px;font-family:${FONT};font-size:12px;line-height:1.6;color:${BRAND.muted};">
          <a href="${url}/dashboard" style="color:${BRAND.violet};text-decoration:none;margin:0 8px;font-weight:600;">Dashboard</a>
          <a href="${url}/help" style="color:${BRAND.violet};text-decoration:none;margin:0 8px;font-weight:600;">Help center</a>
          <a href="${url}/dashboard/support" style="color:${BRAND.violet};text-decoration:none;margin:0 8px;font-weight:600;">Support</a>
          <div style="margin-top:16px;color:${BRAND.ink};font-weight:700;letter-spacing:.4px;">NXEON CLOUD</div>
          <div style="margin-top:4px;color:${BRAND.faint};">High-performance NVMe VPS &middot; game servers &middot; domains</div>
          <div style="margin-top:10px;color:${BRAND.faint};">Nxeon Cloud &middot; 128 Cloudfield Way &middot; Wilmington, DE 19801, USA</div>
          <div style="margin-top:10px;color:${BRAND.faint};">You're receiving this because you have a Nxeon account.</div>
        </td></tr>
      </table>
    </td></tr>
  </table>
</body></html>`;
}

/** Replace `{{ var }}` placeholders with values from `vars` (missing → empty). */
export function substitute(input: string, vars: Record<string, unknown>): string {
  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key: string) => {
    const v = vars[key];
    return v === undefined || v === null ? "" : String(v);
  });
}

/**
 * Minimal built-in defaults used when a template row is missing or disabled.
 * These are intentionally plain — the real, branded copy lives in the DB (see
 * `prisma/seed-email-templates.ts`).
 */
const DEFAULTS: Record<string, { subject: string; body: string }> = {
  welcome: {
    subject: "Welcome to Nxeon",
    body: `${emailHeading("Welcome, {{name}}!")}${emailParagraph("Your Nxeon account is ready. Deploy your first NVMe VPS in minutes.")}`,
  },
  password_reset: {
    subject: "Reset your Nxeon password",
    body: `${emailHeading("Reset your password")}${emailParagraph("Use the button below to set a new password. It expires in 1 hour.")}${emailButton("{{resetUrl}}", "Reset password")}`,
  },
};

const GENERIC_FALLBACK = (key: string) => ({
  subject: "A message from Nxeon",
  body: `${emailHeading("Nxeon")}${emailParagraph(`This notification (<code>${esc(key)}</code>) has no configured template.`)}`,
});

export type RenderedEmail = { subject: string; html: string; template: string };

/**
 * Render a stored (or default) template for `key`, substituting `vars`,
 * returning the final subject and full wrapped HTML ready to send/preview.
 */
export async function renderTemplate(key: string, vars: Record<string, unknown> = {}): Promise<RenderedEmail> {
  let subject: string;
  let body: string;

  let row: { subject: string; html: string; enabled: boolean } | null = null;
  try {
    row = await db.emailTemplate.findUnique({
      where: { key },
      select: { subject: true, html: true, enabled: true },
    });
  } catch {
    row = null;
  }

  if (row && row.enabled) {
    subject = row.subject;
    body = row.html;
  } else {
    const d = DEFAULTS[key] ?? GENERIC_FALLBACK(key);
    subject = d.subject;
    body = d.body;
  }

  const preheader = typeof vars.preheader === "string" ? (vars.preheader as string) : undefined;
  return {
    template: key,
    subject: substitute(subject, vars),
    html: wrapEmail(substitute(body, vars), { preheader }),
  };
}

/**
 * Render a *draft* (unsaved) subject/body with sample vars — used by the admin
 * editor's live preview and by the seed preview. Same wrapping as a real send.
 */
export function renderDraft(subject: string, body: string, vars: Record<string, unknown> = {}): RenderedEmail {
  const preheader = typeof vars.preheader === "string" ? (vars.preheader as string) : undefined;
  return {
    template: "draft",
    subject: substitute(subject, vars),
    html: wrapEmail(substitute(body, vars), { preheader }),
  };
}

/**
 * Append an `EmailLog` row for every send attempt. Never throws (logging must
 * not break a mail flow).
 */
export async function recordEmail(
  toEmail: string,
  subject: string,
  template: string | null,
  html: string,
  status: "SENT" | "FAILED",
  error?: string | null,
  userId?: string | null,
): Promise<void> {
  try {
    await db.emailLog.create({
      data: {
        toEmail,
        subject: subject.slice(0, 500),
        template: template ?? null,
        html,
        status,
        error: error ? String(error).slice(0, 1000) : null,
        userId: userId ?? null,
      },
    });
  } catch (e) {
    console.error("[email-render] failed to record EmailLog:", e);
  }
}

