"use client";

import { useMemo, useState } from "react";

export type EmailTemplate = {
  key: string;
  label: string;
  description: string;
  subject: string;
  sampleArgs: string;
  html: string;
  /** Grouping bucket for the left rail (Account / Billing / Servers / …). */
  category?: string;
};

/**
 * Left-rail selector (grouped by category) + sandboxed live preview of a
 * transactional email. The HTML is rendered inside an isolated iframe (sandbox,
 * no scripts) so the email's inline styles can't leak into the admin panel.
 */
export function EmailTemplatePreview({ templates }: { templates: EmailTemplate[] }) {
  const [active, setActive] = useState(templates[0]?.key ?? "");
  const current = templates.find((t) => t.key === active) ?? templates[0];

  // Preserve first-seen category order so the rail reads Account → Billing → …
  const grouped = useMemo(() => {
    const map = new Map<string, EmailTemplate[]>();
    for (const t of templates) {
      const cat = t.category ?? "Templates";
      const arr = map.get(cat) ?? [];
      arr.push(t);
      map.set(cat, arr);
    }
    return [...map.entries()];
  }, [templates]);

  if (!current) return null;

  return (
    <div className="grid gap-5 lg:grid-cols-[248px_1fr]">
      {/* Selector */}
      <div className="card h-fit p-2">
        {grouped.map(([cat, items]) => (
          <div key={cat} className="mb-2">
            <p className="section-label px-2 pb-1 pt-2">{cat}</p>
            <div className="space-y-0.5">
              {items.map((t) => (
                <button
                  key={t.key}
                  onClick={() => setActive(t.key)}
                  className={`nav-item w-full text-left ${t.key === active ? "nav-item-active" : ""}`}
                >
                  <span className="truncate">{t.label}</span>
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Preview */}
      <div className="space-y-4">
        <div className="card p-5">
          <p className="section-label">Subject line</p>
          <p className="mt-1 text-base font-semibold text-white">{current.subject}</p>
          <p className="mt-3 text-xs text-slate-400">{current.description}</p>
          <div className="mt-3">
            <p className="section-label">Sample data</p>
            <code className="mt-1 block overflow-x-auto rounded-lg bg-black/30 px-3 py-2 font-mono text-xs text-brand-300">
              emails.{current.key}({current.sampleArgs})
            </code>
          </div>
        </div>

        <div className="card overflow-hidden p-0">
          <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-2.5">
            <p className="text-xs font-medium text-slate-400">Rendered preview</p>
            <p className="text-[11px] text-slate-600">sandboxed · sample data</p>
          </div>
          <iframe
            title={`${current.label} preview`}
            srcDoc={current.html}
            sandbox=""
            className="h-[680px] w-full border-0 bg-white"
          />
        </div>
      </div>
    </div>
  );
}

